#include <stdio.h>
#include <stdlib.h>

// Define the structure for a linked list node
typedef struct Node {
    long value;
    struct Node* next;
} Node;

// Define the head of the linked list
Node* head = NULL;

// Define the number of used nodes
int used = 0;

int main(int argc, char** argv) {
    // Check if the number of arguments is less than 2
    if (argc < 2) {
        printf("EMPTY\n");
        return 0;
    }

    // Iterate over the arguments
    for (int i = 1; i < argc; i++) {
        // Convert the argument to a long integer
        long val = strtol(argv[i], NULL, 10);

        // Create a new node
        Node* new_node = (Node*) malloc(sizeof(Node));
        new_node->value = val;
        new_node->next = NULL;

        // If the list is empty, set the new node as the head
        if (head == NULL) {
            head = new_node;
        } else {
            // Otherwise, insert the new node in the correct position
            Node* current = head;
            if (current->value > val) {
                new_node->next = head;
                head = new_node;
            } else {
                while (current->next != NULL && current->next->value < val) {
                    current = current->next;
                }
                new_node->next = current->next;
                current->next = new_node;
            }
        }
        used++;
    }

    // Print the sorted linked list
    Node* current = head;
    while (current != NULL) {
        printf("%ld ", current->value);
        current = current->next;
    }
    printf("\n");

    return 0;
}
